import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem75 remove garantia de pureza preservando identidade operação e idempotência',()=>{const p={id:'ufHw7Y6qN2oc8ePqgHkj',titulo:'Creatina Monohidratada 500g Growth Supplements - Sem Sabor em Pó',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.titulo,p.titulo);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outra creatina',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.comentario,/100% pura|\b[35] g\b/i);assert.match(x.comentario,/não representa análise laboratorial/);assert.match(x.comentario,/rótulo/);});
